import{G as e,K as t,n,ot as r}from"./chunks/framework.BZpZOnGD.js";var i=JSON.parse(`{"title":"","description":"","frontmatter":{},"headers":[],"relativePath":"documentalist-lab/generate-sample-content/02-document-properties.md","filePath":"documentalist-lab/generate-sample-content/02-document-properties.md"}`),a={name:`documentalist-lab/generate-sample-content/02-document-properties.md`};function o(n,i,a,o,s,c){return r(),e(`div`,null,[...i[0]||=[t(`<h2 id="📋-the-situation" tabindex="-1">📋 The Situation <a class="header-anchor" href="#📋-the-situation" aria-label="Permalink to “📋 The Situation”">​</a></h2><p>Before uploading anything, you want Bob to tell you exactly which properties matter for HR documents — so you know what metadata to include when creating each document.</p><h2 id="💬-prompt-to-bob" tabindex="-1">💬 Prompt to Bob <a class="header-anchor" href="#💬-prompt-to-bob" aria-label="Permalink to “💬 Prompt to Bob”">​</a></h2><ol><li>Click the <strong>+</strong> at the bottom left of the chat input, select <strong>Agent</strong> under <strong>Modes</strong>, and enter the following prompt:<div class="language-"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>Before we upload HR documents to the repository, tell me which </span></span>
<span class="line"><span>properties I should set on each document? What&#39;s the difference between </span></span>
<span class="line"><span>mandatory and optional properties for HRDocument?</span></span></code></pre></div></li></ol><h2 id="🔍-what-bob-does-behind-the-scenes" tabindex="-1">🔍 What Bob Does Behind the Scenes <a class="header-anchor" href="#🔍-what-bob-does-behind-the-scenes" aria-label="Permalink to “🔍 What Bob Does Behind the Scenes”">​</a></h2><ul><li>Calls <code>determine_class</code> with keyword <code>&quot;HRDocument&quot;</code> → confirms symbolic name</li><li>Calls <code>get_class_property_descriptions</code> on <code>&quot;HRDocument&quot;</code> → retrieves all HR-specific properties</li><li>Categorizes them by importance for document creation</li></ul><h2 id="✅-expected-output-from-bob" tabindex="-1">✅ Expected Output from Bob <a class="header-anchor" href="#✅-expected-output-from-bob" aria-label="Permalink to “✅ Expected Output from Bob”">​</a></h2><div class="info custom-block"><p class="custom-block-title custom-block-title-default">INFO</p><p>Good — I have all the properties. Let me now present them clearly, split into system-owned vs. custom business properties, and highlight what the script actually sets.</p><p>The <code>HRDocument</code> class has <strong>110 total properties</strong> returned by the API. The ones that matter for your lab uploads are the <strong>custom business properties</strong> (not system-owned). Here&#39;s a breakdown:</p><hr><h4 id="hrdocument-properties" tabindex="-1">HRDocument Properties <a class="header-anchor" href="#hrdocument-properties" aria-label="Permalink to “HRDocument Properties”">​</a></h4><hr><h5 id="custom-business-properties-—-set-these-on-upload" tabindex="-1">Custom business properties — set these on upload <a class="header-anchor" href="#custom-business-properties-—-set-these-on-upload" aria-label="Permalink to “Custom business properties — set these on upload”">​</a></h5><p>The repository doesn&#39;t enforce requiredness at the API level (all fields technically optional), but from a <strong>lab data quality perspective</strong> there are effectively two tiers:</p><hr><h5 id="core-—-set-on-every-document-lab-2-3-expect-these" tabindex="-1">Core — set on every document (Lab 2 &amp; 3 expect these) <a class="header-anchor" href="#core-—-set-on-every-document-lab-2-3-expect-these" aria-label="Permalink to “Core — set on every document (Lab 2 &amp; 3 expect these)”">​</a></h5><table tabindex="0"><thead><tr><th>Property</th><th>Symbolic Name</th><th>Type</th><th>What to put</th></tr></thead><tbody><tr><td>Document Title</td><td><code>DocumentTitle</code></td><td>STRING</td><td>Filename or descriptive title</td></tr><tr><td>Employee ID</td><td><code>EmployeeID</code></td><td>STRING</td><td>e.g. <code>DUP001</code></td></tr><tr><td>First Name</td><td><code>FirstName</code></td><td>STRING</td><td>e.g. <code>Antoine</code></td></tr><tr><td>Last Name</td><td><code>LastName</code></td><td>STRING</td><td>e.g. <code>Muller</code></td></tr><tr><td>Doc Type</td><td><code>DocType</code></td><td>STRING</td><td>e.g. <code>Payslip</code>, <code>EmploymentContract</code></td></tr><tr><td>Department</td><td><code>Department</code></td><td>STRING</td><td>e.g. <code>Human Resources</code></td></tr></tbody></table><hr><h5 id="enrichment-—-set-when-known-improves-searchability" tabindex="-1">Enrichment — set when known (improves searchability) <a class="header-anchor" href="#enrichment-—-set-when-known-improves-searchability" aria-label="Permalink to “Enrichment — set when known (improves searchability)”">​</a></h5><table tabindex="0"><thead><tr><th>Property</th><th>Symbolic Name</th><th>Type</th><th>What to put</th></tr></thead><tbody><tr><td>Job Role</td><td><code>JobRole</code></td><td>STRING</td><td>e.g. <code>HR Specialist</code></td></tr><tr><td>Company</td><td><code>Company</code></td><td>STRING</td><td><code>Acme Corporation</code></td></tr><tr><td>Company Code</td><td><code>CompanyCode</code></td><td>STRING</td><td><code>ACME-FR</code></td></tr><tr><td>Cost Center</td><td><code>CostCenter</code></td><td>STRING</td><td>e.g. <code>CC-HR-001</code></td></tr><tr><td>Location</td><td><code>Location</code></td><td>STRING</td><td>e.g. <code>Paris, France</code></td></tr><tr><td>Start Date</td><td><code>StartDate</code></td><td>DATE</td><td>e.g. <code>2021-01-10</code></td></tr></tbody></table><hr><h5 id="rarely-needed-in-this-lab" tabindex="-1">Rarely needed in this lab <a class="header-anchor" href="#rarely-needed-in-this-lab" aria-label="Permalink to “Rarely needed in this lab”">​</a></h5><table tabindex="0"><thead><tr><th>Property</th><th>Symbolic Name</th><th>Type</th><th>Notes</th></tr></thead><tbody><tr><td>Personal ID</td><td><code>PersonalID</code></td><td>STRING</td><td>National ID — redacted in generated docs</td></tr><tr><td>Birthdate</td><td><code>Birthdate</code></td><td>DATE</td><td>Not in generated data</td></tr><tr><td>Job Function / Code / Level / Status</td><td>various</td><td>STRING</td><td>Not populated by script</td></tr><tr><td>Employment Type / Current Status</td><td>various</td><td>STRING</td><td>Not populated by script</td></tr><tr><td>Termination Date</td><td><code>TerminationDate</code></td><td>DATE</td><td>Only for exit documents</td></tr><tr><td>SAP fields (<code>SAPEmployeeID</code>, <code>SAPDocId</code>, …)</td><td>various</td><td>STRING</td><td>SAP integration — not relevant here</td></tr><tr><td>Salesforce fields</td><td>various</td><td>—</td><td>Salesforce integration — not relevant here</td></tr></tbody></table><hr><h4 id="system-owned-properties-—-set-automatically-never-touch" tabindex="-1">System-owned properties — set automatically, never touch <a class="header-anchor" href="#system-owned-properties-—-set-automatically-never-touch" aria-label="Permalink to “System-owned properties — set automatically, never touch”">​</a></h4><p>These are managed by Content Cortex and you cannot (and should not) set them manually:</p><table tabindex="0"><thead><tr><th>Property</th><th>Set by</th></tr></thead><tbody><tr><td><code>Creator</code>, <code>DateCreated</code>, <code>LastModifier</code>, <code>DateLastModified</code></td><td>Repository on create/update</td></tr><tr><td><code>Id</code>, <code>VersionSeries</code>, <code>MajorVersionNumber</code>, <code>MinorVersionNumber</code></td><td>Repository versioning engine</td></tr><tr><td><code>ContentSize</code>, <code>MimeType</code></td><td>Repository on content upload</td></tr><tr><td><code>IsCurrentVersion</code>, <code>IsReserved</code>, <code>IsFrozenVersion</code></td><td>Check-in/check-out system</td></tr><tr><td><code>DateCheckedIn</code>, <code>VersionStatus</code></td><td>Check-in system</td></tr></tbody></table><hr><h4 id="the-lab-3-difference-—-what-the-seeded-errors-break" tabindex="-1">The Lab 3 difference — what the seeded errors break <a class="header-anchor" href="#the-lab-3-difference-—-what-the-seeded-errors-break" aria-label="Permalink to “The Lab 3 difference — what the seeded errors break”">​</a></h4><p>The 5 seeded errors all violate the <strong>core properties</strong> tier:</p><table tabindex="0"><thead><tr><th>Error type</th><th>Missing/wrong core property</th></tr></thead><tbody><tr><td>Base <code>Document</code> class (DUP001, DUP004)</td><td><strong>All</strong> — wrong class, no properties at all</td></tr><tr><td>Wrong class <code>Contract</code> (DUP002)</td><td>Wrong class + missing <code>Department</code></td></tr><tr><td>Wrong EmployeeID (DUP003)</td><td><code>EmployeeID</code> = <code>000000</code> instead of <code>DUP003</code></td></tr><tr><td>Missing fields (DUP005)</td><td>Missing <code>Department</code> + <code>DocType</code></td></tr></tbody></table><p>The metadata comment block at the bottom of each generated <code>.txt</code> file tells you exactly which properties to set for that specific document when uploading.</p></div><h2 id="💡-key-insights" tabindex="-1">💡 Key Insights <a class="header-anchor" href="#💡-key-insights" aria-label="Permalink to “💡 Key Insights”">​</a></h2><p>The most critical design pattern here is using <strong>properties as discriminators</strong>. Instead of creating separate document classes for Payslips, Contracts, and Performance Reviews, all files share a single <code>HRDocument</code> class differentiated by the <code>DocType</code> property. While metadata follows a tiered structure — distinguishing essential core properties (like <code>EmployeeID</code> and <code>DocType</code>) from optional enrichment fields (like <code>JobRole</code> or <code>Location</code>) — using <code>DocType</code> as a discriminator prevents class explosion, keeps the taxonomy manageable, and enables flexible cross-document querying.</p>`,10)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};